export const ASCENDED_FORMS={legendary:{attack:'蒼穹曜翼獅鷲',magic:'霜月九尾靈狐',defense:'琥珀山脈晶犀',support:'聖光星冠獨角獸'},mythic:{attack:'赤曜裂界龍皇',magic:'星焰輪迴神凰',defense:'終界玄岩泰坦',support:'太初玉麟聖君'}};
export const ASCENSION_COST={ascend:{essence_4:30,ascension_core:10},mutate:{essence_4:50,ascension_core:20}};
export const petLevelCap=(pet,ownerReborn=false)=>pet.ascended||ownerReborn?150:99;
export function ascensionError(pet,bag,location,mode='ascend'){if(!['town','skycity'].includes(location))return '請回村莊進行界限進化';if(!pet||!['legendary','mythic'].includes(pet.rarity))return '需要傳說或神話寵物';if(pet.level<99||pet.evolution<4)return '需要99級且完成四次一般進化';if(mode==='ascend'&&pet.ascended)return '已完成界限進化';if(mode==='mutate'&&(!pet.ascended||pet.rarity!=='legendary'))return '異化僅適用界限傳說寵物';const cost=ASCENSION_COST[mode];if(!cost)return '無效進化方式';return Object.entries(cost).some(([id,n])=>(bag.find(e=>e.id===id)?.qty||0)<n)?'進化素材不足':null;}
export function ascendPet(pet,bag,location,mode='ascend',rng=Math.random){const error=ascensionError(pet,bag,location,mode);if(error)return {error};const before=pet.rarity;for(const [id,n] of Object.entries(ASCENSION_COST[mode]))bag.find(e=>e.id===id).qty-=n;for(let i=bag.length-1;i>=0;i--)if(!bag[i].uid&&bag[i].qty===0)bag.splice(i,1);const mutation=before==='legendary'&&rng()<(mode==='mutate'?.15:.05);pet.ascended=true;if(mutation)pet.rarity='mythic';return {before,after:pet.rarity,mutation,ascended:true};}
export function normalizeLoyalty(pet){pet.loyalty=Math.max(0,Math.min(10000,Math.floor(Number(pet.loyalty)||0)));return pet;}
export function awardLoyalty(pet,monsterLevel){if(!pet||pet.hp<=0||Math.abs(pet.level-monsterLevel)>40)return 0;normalizeLoyalty(pet);const gain=pet.loyalty<10000?1:0;pet.loyalty+=gain;return gain;}
